        pa, pb = pt(a), pt(b)
        if pa is not None and pb is not None:
            dx = pa[0] - pb[0]
            dy = pa[1] - pb[1]
            return (dx * dx + dy * dy) ** 0.5
        return 0 if a == b else 1

    if cap is None:
        cap = sum(dem(c) for c in customers)
        if cap <= 0:
            cap = 1

    dep = pt(depot)
    if dep is not None:
        def key(c):
            p = pt(c)
            if p is None:
                return (10.0, 0.0, c)
            dx = p[0] - dep[0]
            dy = p[1] - dep[1]
            ang = dy / (abs(dx) + abs(dy) + 1e-12) if dx >= 0 else 2.0 - dy / (abs(dx) + abs(dy) + 1e-12)
            return (ang, dx * dx + dy * dy, c)
        order = sorted(customers, key=key)
    else:
        order = sorted(customers, key=lambda c: (-dem(c), c))

    routes, cur, load = [], [], 0
    for c in order:
        dc = dem(c)
        if dc > cap:
            if cur:
                routes.append(cur)
                cur, load = [], 0
            routes.append([c])
        elif load + dc <= cap:
            cur.append(c)
            load += dc
        else:
            if cur:
                routes.append(cur)
            cur, load = [c], dc
    if cur:
        routes.append(cur)

    def cost(r):
        if not r:
            return 0
        s = d(depot, r[0]) + d(r[-1], depot)
        for i in range(len(r) - 1):
            s += d(r[i], r[i + 1])
        return s

    def two_opt(r):
        n = len(r)
        if n < 4:
            return r
        improved = True
        while improved:
            improved = False
            best = 0
            bi = bj = None
            for i in range(n - 2):
                a = depot if i == 0 else r[i - 1]
                b = r[i]
                for j in range(i + 2, n):
                    c = r[j - 1]
                    e = depot if j == n else r[j]
                    delta = (d(a, c) + d(b, e)) - (d(a, b) + d(c, e))
                    if delta < best - 1e-12:
                        best, bi, bj = delta, i, j
            if bi is not None:
                r = r[:bi] + list(reversed(r[bi:bj])) + r[bj:]
                n = len(r)
                improved = True
        return r

    def load_of(r):
        s = 0
        for c in r:
            s += dem(c)
        return s

    routes = [two_opt(r) for r in routes if r]

    changed = True
    while changed and len(routes) > 1:
        changed = False
        for i in range(len(routes)):
            if changed:
                break
            ri = routes[i]
            for p in range(len(ri)):
                c = ri[p]
                dc = dem(c)
                pre = depot if p == 0 else ri[p - 1]
                nex = depot if p == len(ri) - 1 else ri[p + 1]
                rem = d(pre, nex) - d(pre, c) - d(c, nex)
                best_j, best_k, best_gain = None, None, 0
                for j in range(len(routes)):
                    if i == j or load_of(routes[j]) + dc > cap:
                        continue
                    rj = routes[j]
                    for k in range(len(rj) + 1):
                        l = depot if k == 0 else rj[k - 1]
                        rgt = depot if k == len(rj) else rj[k]
                        ins = d(l, c) + d(c, rgt) - d(l, rgt)
                        gain = rem - ins
                        if gain > best_gain + 1e-12:
                            best_gain, best_j, best_k = gain, j, k
                if best_j is not None:
                    routes[i] = ri[:p] + ri[p + 1:]
                    routes[best_j] = routes[best_j][:best_k] + [c] + routes[best_j][best_k:]
                    routes = [r for r in routes if r]
                    changed = True
                    break

    seen = {}
    for r in routes:
        for c in r:
            seen[c] = seen.get(c, 0) + 1

    missing = [c for c in customers if seen.get(c, 0) == 0]
    if missing:
        left = sorted(missing, key=lambda c: (dem(c), c))
        for c in left:
            dc = dem(c)
            placed = False
            best = None
            for i in range(len(routes)):
                if load_of(routes[i]) + dc > cap:
                    continue
                rr = routes[i]
                for k in range(len(rr) + 1):
                    l = depot if k == 0 else rr[k - 1]
                    rgt = depot if k == len(rr) else rr[k]
                    add = d(l, c) + d(c, rgt) - d(l, rgt)
                    if best is None or add < best[0]:
                        best = (add, i, k)
            if best is None:
                routes.append([c])
            else:
                _, i, k = best
                rr = routes[i]
                routes[i] = rr[:k] + [c] + rr[k:]

    return [r for r in routes if r]
